let text = matpower::to_matpower(&sys)?;
let reparsed = matpower::from_matpower(&text)?; // A second round trip is byte-identical.
assert_eq!(matpower::to_matpower(&reparsed)?, text);
# Ok::<(), Box<dyn std::error::Error>>(())

